<?php  /** @noinspection PhpUndefinedVariableInspection */ ?>

<?php
/**
 * Do not edit this file directly.  You can copy this file to your theme directory
 * in /your-theme/woocommerce-pay-per-post/shortcode-has_access-polylang.php
 * The $purchased variable is a WP Posts Object of purchased posts.
 */
?>
<div class="wc-ppp-purchased-container">
	<?php if ( count( $purchased ) > 0 ) :
        if(function_exists('pll_current_language')){
            $current_language = pll_current_language();
        }

        ?>
        <ul id="what-ever-you-want">
			<?php foreach ( $purchased as $post ) : /** @noinspection PhpUndefinedFunctionInspection */
				$languages = pll_get_post_translations($post->ID);
				// A post with no translation in the current language is listed as
				// itself. Looking that translation up gave null, and
				// get_permalink( null ) links to the page the list is on.
				$display_id       = $languages[ $current_language ] ?? $post->ID;
				$display_language = array_search( $display_id, $languages ); ?>
                <li>
                    <strong><a href="<?php echo esc_url( get_permalink( $display_id ) ); ?>"><?php if ( $display_language ) : ?>[<?php echo esc_html( $display_language ); ?>] <?php endif; ?><?php echo esc_html( get_the_title( $display_id ) ); ?></a></strong><br>
                    <?php if ( count( $languages ) > 1 ): ?>
                    <?php apply_filters( 'wc_pay_per_post_languages_title', esc_html__( 'Additional Languages', 'wc_pay_per_post' ) ) ?>
                    <ul>
	                    <?php foreach($languages as $language => $post_id): if( (int) $post_id === (int) $display_id ): continue; endif; ?>
                            <li><a href="<?php echo esc_url( get_permalink( $post_id ) ); ?>">[<?php echo $language; ?>] <?php echo esc_html( get_the_title($post_id) ); ?></a></li>
	                    <?php endforeach; ?>
                    </ul>
                    <?php endif;  ?>
                </li>
			<?php endforeach; ?>
        </ul>
	<?php else : ?>
        <p><?php /** @noinspection PhpVoidFunctionResultUsedInspection */
                apply_filters('wc_pay_per_post_shortcode_has_access_no_posts', _e('You have not have access to any protected posts.', 'wc_pay_per_post' ) ); ?></p>
	<?php endif; ?>
</div>